// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0) && newOwner != address(this));
        // Call addReward to satisfy the condition
        c.addReward(address(0x1));
        // The rule: after addReward, onlyOwner functions should work for the owner
        // Here we test that transferOwnership succeeds when called by owner
        c.transferOwnership(newOwner);
        bool succeeded = (c.owner() == newOwner);
        assertTrue(succeeded, "transferOwnership should succeed when called by owner");
    }
}

